// Nova Atelier — hub-pricing list row (parallax-plane render mode)
import * as THREE from 'three/webgpu';
import { texture, uv, vec2, float, uniform, positionLocal, normalLocal, MeshStandardNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-row';
  group.position.set(1.25, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;
  const depthMap = ctx.textureLoader.load(depthMapUrl);

  // atlas region UV remap
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = 512;
  const uvOffset = vec2(atlasRect.x / atlasSize, atlasRect.y / atlasSize);
  const uvScale = vec2(atlasRect.w / atlasSize, atlasRect.h / atlasSize);
  const remappedUV = uv().mul(uvScale).add(uvOffset);

  const displacementStrength = uniform(0.08);
  const depthSample = texture(depthMap, remappedUV).r;
  const displacedPosition = positionLocal.add(
    normalLocal.mul(depthSample.sub(0.5)).mul(displacementStrength)
  );

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(map, remappedUV);
  material.positionNode = displacedPosition;
  material.roughness = 0.55;
  material.metalness = 0.4;
  material.clearcoat = 0.2;
  material.envMapIntensity = 1.0;

  const geometry = new THREE.PlaneGeometry(3.2, 0.5, 64, 64);
  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-row-plane';
  group.add(plane);

  // subtle divider line beneath row (machined-metal accent)
  const dividerGeo = new THREE.PlaneGeometry(3.2, 0.008);
  const dividerMat = new THREE.MeshStandardMaterial({
    color: colors.paper,
    roughness: 0.6,
    metalness: 0.5,
    transparent: true,
    opacity: 0.35,
  });
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.24, 0.001);
  group.add(divider);

  // accent rim light (small point light for machined-metal rim highlight)
  const rimLight = new THREE.PointLight(colors.accent, 0.6, 2.5);
  rimLight.position.set(1.2, 0.3, 0.6);
  group.add(rimLight);

  // Apply cinematic primitives from config (required, never inline)
  const appliedPrimitiveHandles = [];
  const primitivesConfig = config.cinematicPrimitives || [
    { name: 'parallax-scroll', trigger: 'scroll', params: { intensity: 0.4 } },
    { name: 'depth-rotate', trigger: 'hover', params: { maxDeg: 8 } },
  ];

  primitivesConfig.forEach((prim) => {
    if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
      const handle = ctx.primitives[prim.name](group, prim.params || {});
      appliedPrimitiveHandles.push(handle);
    }
  });

  // Interaction state
  let hoverTimeline = null;
  const baseY = group.position.y;

  const onHoverIn = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
    hoverTimeline.fromTo(group.position, { z: group.position.z }, {
      z: group.position.z,
      duration: 0.01,
    }, 0);
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      },
    });

    if (ctx.emit) {
      ctx.emit('hub-pricing.select', { nodeId: 'hub-pricing-row' });
    }
  };

  // Weighted-settle entrance animation
  group.position.y = baseY - 0.4;
  const settleTl = gsap.timeline();
  settleTl.to(group.position, {
    y: baseY,
    duration: 0.9,
    ease: 'power4.out',
  });
  group.scale.set(0.98, 0.98, 0.98);
  settleTl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  settleTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.4,
    ease: 'power4.out',
  }, 0.5);

  group.userData.handlers = {
    hover: onHoverIn,
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
  };

  group.userData.dataBindings = {
    confirmPanel: null,
  };

  if (ctx.trpcSubscribe && typeof ctx.trpcSubscribe === 'function') {
    group.userData.unsubscribeBooking = ctx.trpcSubscribe(
      'visits.book',
      (result) => {
        group.userData.dataBindings.confirmPanel = result?.slot ?? null;
      }
    );
  }

  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (settleTl) settleTl.kill();

    appliedPrimitiveHandles.forEach((handle) => {
      if (handle && typeof handle.dispose === 'function') {
        handle.dispose();
      }
    });

    if (typeof group.userData.unsubscribeBooking === 'function') {
      group.userData.unsubscribeBooking();
    }

    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();

    if (map && typeof map.dispose === 'function') map.dispose();
    if (depthMap && typeof depthMap.dispose === 'function') depthMap.dispose();

    group.remove(rimLight);
    group.remove(plane);
    group.remove(divider);
  };

  return group;
}
